insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('eko',0,'Kenali Ekosistem Djiwa Tentram','{manager,supervisor}',$j${"id":"eko","t":"Kenali Ekosistem Djiwa Tentram","ic":"dashboard-overview","who":"MS","when":"Hari pertama","goal":"Tahu setiap aplikasi, siapa pemakainya, dan ke mana data mengalir, supaya tahu ke mana harus melihat saat ada masalah.","steps":["Buka aplikasi Customer. Ini yang dipakai pelanggan: pesan menu, isi dompet, booking, dan ikut program Jumat Berkah. Coba buat satu pesanan percobaan.","Buka POS (kasir). Kenali menu transaksi, tombol buka/akhiri shift, dan notifikasi pesanan. Lihat juga bagaimana pesanan dine-in, takeaway, dan online dibedakan.","Buka aplikasi Karyawan. Di sinilah tim absen masuk dan keluar (PIN atau wajah, plus lokasi GPS), melihat jadwal, slip gaji, dan mengisi checklist serta opname saat pulang.","Buka Admin. Kenali menu Pesanan, Bar, Dapur, Produk, Resep & HPP, Inventaris, Keuangan, Tim Operasional, Diskon, Booking, dan Jumat Berkah.","Kenali Telegram: grup Transaksi dan grup Kitchen menerima laporan otomatis. Setiap absen keluar mengirim laporan ke grup dan pesan pribadi ke karyawan.","Masuk ke panel Manager (manager.djiwatentram.web.id) dengan akun Google. Saat pertama kali, pilih peran Manager atau Supervisor, lalu tunggu owner menyetujui akses di admin.djiwatentram.web.id.","Di panel Manager tersedia tugas harian dari AI, monitor realtime, keuangan, laporan, dan semua dokumen."],"auto":["Semua aplikasi memakai satu database (Supabase), sehingga pesanan, stok, kas, dan absensi selalu sinkron.","Perubahan di POS langsung terlihat di Admin dan panel Manager (realtime, cadangan polling 30 detik)."],"th":["Aplikasi","Pemakai","Fungsi"],"table":[["Customer","Pelanggan","Pesan menu, dompet, booking, Jumat Berkah"],["POS","Kasir","Transaksi, buka/tutup shift, notifikasi pesanan"],["Karyawan","Semua karyawan","Absen, jadwal, slip gaji, checklist & opname saat pulang"],["Admin","Owner, Manager","Pesanan, produk, resep, inventaris, keuangan, tim"],["Panel Manager","Manager, Supervisor","Tugas dari AI, monitor, dokumen, Playbook"]],"issue":[["Data di dua aplikasi berbeda","Refresh dulu. Bila tetap beda setelah 1 menit, catat aplikasi, halaman, dan jam, lalu laporkan ke owner."]],"docs":["cheat-sheet"],"open":["POS","Customer","Karyawan","Admin"]}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('ritme',1,'Ritme Satu Hari di Toko','{manager,supervisor}',$j${"id":"ritme","t":"Ritme Satu Hari di Toko","ic":"work-schedule","who":"MS","when":"Hari pertama","goal":"Memahami urutan kejadian dalam sehari supaya tahu kapan harus ada di mana dan apa yang harus selesai.","steps":["Pelajari tabel ritme harian di bawah. Jam bisa disesuaikan dengan jadwal toko.","Tandai tiga titik paling penting untuk peran Anda. Manager: verifikasi buka, jam sibuk, verifikasi tutup. Supervisor: cek stok pagi, penerimaan barang siang, ringkasan belanja sore.","Buka tab Tugas Hari Ini setiap pagi setelah notifikasi AI masuk, lalu kerjakan dari yang berprioritas Tinggi."],"auto":["Tugas harian disusun AI dari data nyata; tugas baru muncul otomatis saat ada kejadian (stok habis, antrean lama, belum clock-in)."],"th":["Jam","Kegiatan"],"table":[["06:00","Cleaning masuk, area makan dan toilet dibersihkan"],["07:00","Shift pagi: barista dan kitchen clock-in, cek mesin dan kulkas"],["07:30","Kasir buka shift dan mengisi kas awal; Supervisor cek stok"],["10:00","Manager review laporan shift kemarin dan putuskan approval"],["12:00–13:30","Jam sibuk makan siang: pantau antrean dan waktu tunggu"],["15:00","Pergantian shift; serah terima catatan"],["21:00 (Kamis)","Pesanan Jumat Berkah ditutup, rekap MASAK terkirim"],["21:30","Kasir tutup shift; Manager verifikasi kas"],["22:00","Manager menulis laporan harian ke owner"]],"issue":[],"docs":["checklist-buka-tutup"],"open":[],"draft":"Jam shift di atas adalah contoh; sesuaikan dengan pengaturan jadwal shift di Admin."}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('buka',2,'Buka Toko','{manager,supervisor}',$j${"id":"buka","t":"Buka Toko","ic":"cashier-terminal","who":"MS","when":"Sebelum jam buka","goal":"Toko siap melayani: tim hadir, shift dibuka dengan kas awal yang benar, stok dan menu aman.","steps":["Cek jadwal hari ini di Admin → Tim Operasional → Jadwal. Catat siapa jaga di bar, dapur, kasir, dan cleaning.","Pastikan setiap karyawan clock-in lewat aplikasi Karyawan (PIN atau wajah, lokasi harus di toko). Yang belum clock-in 15 menit setelah jadwal: hubungi langsung.","Kasir membuka shift di POS dan mengisi kas awal (modal awal) setelah menghitung uang di laci. Pastikan angka yang diketik sama dengan uang fisik.","Cek kartu Stok Menipis di Inventaris atau Stock Overview. Bahan di bawah batas minimum diteruskan ke Supervisor untuk dibuat PO.","Cek menu dan harga di POS. Pastikan menu yang habis ditandai, dan promo atau Happy Hour yang aktif benar.","Keliling area makan, bar, dan dapur: kebersihan, peralatan menyala (mesin kopi, kulkas, kompor), display rapi. Centang checklist buka."],"auto":["Shift tercatat: nama shift, kasir, jam mulai, kas awal.","Kas awal otomatis dicatat sebagai transaksi \"Modal Awal\".","Jadwal karyawan unik per orang, per tanggal, per shift; clock-in menandai status jadwal."],"issue":[["Karyawan tidak bisa clock-in","Periksa PIN dan GPS (izin lokasi aktif, berada di toko). Bila gagal berulang, catat absensi manual dan minta karyawan hubungi Manager."],["Kasir lupa buka shift","Buka shift sebelum transaksi pertama; transaksi tanpa shift membuat laporan shift tidak lengkap."],["Kas awal salah ketik","Segera beri tahu Manager; koreksi dilakukan Manager di Admin dan dicatat di catatan harian."]],"docs":["checklist-buka-tutup"],"open":["Admin → Tim Operasional","POS → Shift","Karyawan → Absen"]}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('ops',3,'Selama Operasional: Pesanan, Bar & Dapur','{manager,supervisor}',$j${"id":"ops","t":"Selama Operasional: Pesanan, Bar & Dapur","ic":"order-queue","who":"MS","when":"Sepanjang jam buka","goal":"Setiap pesanan tertangani cepat dan benar, status selalu terbarui, tidak ada pesanan atau pembayaran yang tertinggal.","steps":["Pantau antrean di Admin → Pesanan atau panel Manager. Pesanan dibedakan dine-in, takeaway, dan online; masing-masing punya nomor struk harian sendiri.","Pastikan status bergerak: baru → sedang dibuat → selesai. Bar dan dapur memperbarui statusnya masing-masing; pesanan yang selesai harus ditandai agar stok berkurang.","Jam sibuk: targetkan waktu tunggu di bawah 10 menit. Bila antrean melewati 15 menit, AI akan membuat tugas baru; segera cek siapa yang kewalahan dan bantu.","Pembayaran QRIS atau online yang belum lunas: tunggu rekonsiliasi otomatis, jangan membuat transaksi baru untuk pesanan yang sama.","Pesanan delivery yang batal: batalkan open bill, jangan dihapus, supaya jejak transaksi tetap ada.","Komplain pelanggan: minta maaf, tawarkan solusi (buat ulang atau diskon sesuai kebijakan), lalu catat di Laporan Insiden."],"auto":["Nomor struk naik otomatis per hari per jenis pesanan.","Saat pesanan selesai: pendapatan tercatat dan bahan berkurang otomatis sesuai resep.","Setiap item menyimpan snapshot HPP saat dibuat, supaya laporan laba akurat walau harga bahan berubah.","Pembayaran online yang terlewat direkonsiliasi otomatis pada pemrosesan berikutnya."],"issue":[["Pesanan tertahan di status baru","Cek apakah bar atau dapur sudah melihatnya. Bila perlu, pindahkan status manual dan beri tahu tim."],["Pelanggan sudah bayar tetapi pesanan belum lunas","Tunggu beberapa menit untuk rekonsiliasi; bila tetap belum, catat nomor pesanan dan bukti bayar, lalu laporkan ke owner."],["Pesanan salah dibuat","Buat ulang, catat bahan terbuang sebagai insiden agar stok dan HPP tetap masuk akal."]],"docs":["laporan-insiden-komplain"],"open":["POS → Menu","Admin → Pesanan","Admin → Bar / Dapur"]}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('tutup',4,'Tutup Shift, Absen Keluar & Kas','{manager,supervisor}',$j${"id":"tutup","t":"Tutup Shift, Absen Keluar & Kas","ic":"shift-closing","who":"MS","when":"Akhir shift / akhir hari","goal":"Kas fisik cocok dengan sistem, checklist kebersihan lengkap, dan laporan shift terverifikasi sebelum Anda pulang.","steps":["Kasir menghitung uang tunai per pecahan (100.000, 50.000, 20.000, 10.000, 5.000, 2.000, 1.000, 500, 200, 100) lalu mengakhiri shift di POS.","Kasir mengonfirmasi nominal non-tunai (QRIS) sesuai laporan pembayaran dan mengisi pengeluaran shift dengan keterangan jelas.","Tiap karyawan absen keluar lewat aplikasi Karyawan: verifikasi PIN atau wajah, izinkan lokasi GPS, lalu isi checklist wajib: Bar & Kitchen, Area Customer, dan Toilet/WC, masing-masing berstatus Bersih atau Perlu Perbaikan.","Karyawan bar dan dapur wajib stok opname sebelum absen keluar selesai.","Manager membuka Admin → Keuangan → Laporan Shift, lalu memeriksa ringkasan, selisih tunai dan non-tunai, dan rincian pecahan.","Selisih Rp10.000 atau lebih ditandai perlu perhatian. Tanyakan penyebabnya ke kasir, lalu isi Berita Acara Selisih Kas.","Pastikan laporan masuk ke grup Telegram dan pesan \"Absen Keluar Berhasil\" diterima karyawan. Lalu centang checklist tutup: peralatan mati, sampah dibuang, toko dikunci."],"auto":["Setoran akhir dan pengeluaran detail tercatat sebagai transaksi keuangan.","Sistem membuat rekonsiliasi: selisih kas sistem vs fisik, status seimbang atau tidak seimbang.","Jurnal akuntansi double-entry dibuat otomatis untuk setiap transaksi.","Absen keluar menahan proses bila jadwal shift belum bisa dibaca; checklist yang tidak lengkap ditolak sistem.","Shift yang lupa ditutup akan ditutup otomatis oleh sistem; pengeluaran berulang ikut dicatat."],"issue":[["Selisih kas","Hitung ulang per pecahan, cek pengeluaran yang belum dicatat, lalu isi Berita Acara Selisih Kas. Jangan menutup buku tanpa penjelasan."],["Absen keluar ditolak: checklist tidak lengkap","Isi ketiga bagian (Bar & Kitchen, Area Customer, Toilet/WC) dengan status Bersih atau Perlu Perbaikan."],["Absen keluar ditolak: lokasi tidak tersedia","Aktifkan GPS dan izinkan lokasi di browser/ponsel, lalu coba lagi."],["Laporan Telegram tidak masuk","Absen keluar tetap tersimpan. Catat di laporan harian dan kabari owner; laporan shift tetap ada di Admin."]],"docs":["berita-acara-selisih-kas","checklist-buka-tutup"],"open":["POS → Akhiri Shift","Karyawan → Absen Keluar","Admin → Keuangan → Laporan Shift"],"draft":"Batas toleransi selisih kas yang boleh diterima tanpa tindak lanjut belum ditetapkan; ambang Rp10.000 hanya penanda di Admin."}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('stok',5,'Stok & Stok Opname','{manager,supervisor}',$j${"id":"stok","t":"Stok & Stok Opname","ic":"stock-opname","who":"MS","when":"Harian & saat pulang shift","goal":"Stok di sistem sama dengan stok fisik, dan bahan yang menipis terdeteksi sebelum habis.","steps":["Pastikan karyawan bar dan dapur melakukan opname sebelum absen keluar. Hitung fisik dulu, baru isi angka; jangan menyalin angka sistem.","Tinjau selisih opname di Admin → Inventaris atau Stock Overview. Selisih berulang pada bahan yang sama berarti resep atau porsi perlu diperiksa.","Cek bahan di bawah batas minimum (low stock). Teruskan ke Supervisor agar PO dibuat sebelum bahan habis.","Terapkan FIFO: bahan lama dipakai lebih dulu; cek tanggal kedaluwarsa saat menata.","Saat harga beli berubah, perbarui harga beli terakhir di Inventaris agar HPP resep dan menu ikut akurat.","Audit stok bulanan: hitung penuh gudang, bandingkan dengan sistem, dan simpan Laporan Stok Opname.","Pastikan satuan beli seperti karton, pack, atau tray punya konversi ke satuan dasar (misalnya 1 karton = 50 pcs). Konfirmasi sekali di menu Stok & Opname atau saat meninjau struk; setelahnya otomatis, dan stok selalu dicatat dalam satuan dasar.","Hitung opname bertingkat (misalnya 2 karton + 7 pcs); sistem menjumlahkannya. Ikuti aturan di Stok & Opname: hitung buta, jadwal, dan toleransi selisih per bahan."],"auto":["Stok berkurang otomatis dari resep saat pesanan selesai.","Peringatan stok menipis muncul bila jumlah ≤ batas minimum bahan dan terkirim ke Telegram.","Perubahan harga beli memengaruhi HPP resep dan menu."],"issue":[["Stok minus atau tidak masuk akal","Biasanya resep belum lengkap, satuan salah, atau opname terlewat. Opname ulang lalu perbaiki resep di Admin → Resep."],["Bahan habis padahal sistem masih ada","Catat selisih di Laporan Opname dan telusuri: porsi berlebih, bahan terbuang, atau penerimaan barang belum dicatat."]],"docs":["laporan-opname"],"open":["Admin → Inventaris","Admin → Stock Overview","Karyawan → Opname"]}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('po',6,'Belanja & Purchase Order','{supervisor}',$j${"id":"po","t":"Belanja & Purchase Order","ic":"suppliers-purchase-order","who":"S","when":"Saat stok menipis / jadwal belanja","goal":"Bahan tersedia sebelum habis, pembelian tercatat rapi dengan nota, dan harga terpantau.","steps":["Buka Belanja & PO. Lihat bahan di bawah minimum beserta perkiraan sisa hari pemakaian.","Periksa draf PO dari AI: bahan, jumlah, supplier, dan estimasi biaya. Ubah jumlah bila ada stok titipan atau promo supplier. Anda boleh menerbitkan PO sendiri tanpa approval.","Hubungi supplier (telepon atau chat), konfirmasi harga, jumlah, dan jadwal kirim. Simpan bukti konfirmasi lalu ubah status PO menjadi Dipesan.","Saat barang tiba, cocokkan dengan PO: jumlah, kualitas, suhu (bahan dingin), dan tanggal kedaluwarsa. Isi Berita Acara Terima Barang.","Barang sesuai: ubah status ke Diterima; stok bertambah dan pengeluaran tercatat. Barang kurang atau rusak: terima sebagian dan isi Berita Acara Retur.","Simpan nota atau foto nota, perbarui harga beli terakhir, lalu kirim ringkasan belanja ke Manager di sore hari.","Tiap minggu bandingkan harga beberapa supplier untuk bahan utama dan isi Perbandingan Supplier."],"auto":["PO diterima → stok bertambah, tugas terkait selesai otomatis, pengeluaran tercatat di Keuangan.","Draf PO untuk bahan menipis dibuat AI dari data stok nyata."],"issue":[["Barang datang tidak sesuai PO","Terima sebagian, foto barang, isi Berita Acara Retur, dan hubungi supplier. Beri tahu Manager bila nilainya besar."],["Harga naik dibanding biasanya","Jangan langsung memesan. Beri tahu Manager dan minta penawaran pembanding agar HPP dan harga jual bisa ditinjau."],["Supplier tidak bisa kirim hari ini","Cari supplier cadangan, pesan secukupnya, dan tandai menu terdampak habis di POS."]],"docs":["form-po","berita-acara-terima-barang","berita-acara-retur","perbandingan-supplier","laporan-belanja-mingguan"],"open":["Panel Manager → Belanja & PO","Admin → Inventaris"],"draft":"Modul PO terstruktur (supplier, item, status) adalah fitur baru; alur ini adalah target desain."}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('tim',7,'Kelola Tim, Absensi & Approval','{manager}',$j${"id":"tim","t":"Kelola Tim, Absensi & Approval","ic":"employee-profile","who":"M","when":"Harian & mingguan","goal":"Tim hadir sesuai jadwal, pengajuan diputuskan cepat dan adil, karyawan baru terdaftar benar.","steps":["Tinjau kehadiran pagi hari: siapa belum clock-in, terlambat, atau izin. Hubungi yang belum hadir dan siapkan pengganti bila perlu.","Buka Approval dan putuskan pengajuan. Jenis yang ada: izin, cuti, sakit, dan lainnya. Tulis alasan singkat bila menolak.","Tukar shift: setujui hanya bila bar, dapur, dan kasir tetap terisi pada jam tersebut.","Susun jadwal minggu depan paling lambat hari Sabtu; publikasikan di Tim Operasional → Jadwal.","Karyawan baru: tinjau pendaftaran di Admin → Onboarding, periksa data, lalu setujui. Sistem membuat akun, PIN, dan NIP otomatis.","Beri umpan balik karyawan secara berkala dan catat di Evaluasi Karyawan; sampaikan hal penting ke owner.","Buka Tim & Gaji. Gaji berjalan tiap karyawan bertambah otomatis dari absensi (masuk dan keluar). Tambahkan bonus, denda, atau lembur tambahan lewat Bonus & denda; nilai di atas batas Owner menunggu persetujuan.","Saat periode ditutup (cutoff), buat slip gaji, periksa rinciannya, lalu kirim. Slip muncul di aplikasi Karyawan (dan Telegram); karyawan menerima atau mengajukan koreksi. Koreksi menjadi tugas untuk Anda."],"auto":["Keputusan izin tersimpan dengan audit log dan notifikasi push ke karyawan.","Saat karyawan baru disetujui, akun, PIN, dan NIP dibuat dan ucapan selamat datang terkirim via Telegram.","Gaji shift dan tunjangan masuk ke periode otomatis setiap karyawan absen keluar; denda terlambat dihitung dari menit keterlambatan.","Slip gaji dikirim ke aplikasi Karyawan; status diterima atau koreksi kembali ke Manager dan Admin.","Karyawan dinonaktifkan → semua sesi login dicabut."],"issue":[["Karyawan lupa clock-out","Catat koreksi absensi sebagai tugas. Pastikan checklist dan opname tetap dilakukan hari itu."],["Dua orang minta izin di hari sama","Setujui yang lebih dulu mengajukan bila jadwal masih terisi; carikan pengganti untuk yang lain dan jelaskan alasannya."],["Karyawan tidak hadir tanpa kabar","Hubungi langsung, catat sebagai tidak hadir tanpa keterangan, dan laporkan ke owner di laporan harian."]],"docs":["evaluasi-karyawan","notulen-rapat"],"open":["Panel Manager → Tim & SDM","Admin → Tim Operasional","Admin → Onboarding"],"draft":"Aturan lembur, sanksi keterlambatan, dan batas izin per bulan belum didefinisikan; perlu keputusan owner."}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('uang',8,'Keuangan: Membaca Revenue & Pengeluaran','{manager}',$j${"id":"uang","t":"Keuangan: Membaca Revenue & Pengeluaran","ic":"sales-report","who":"M","when":"Harian & mingguan","goal":"Memahami angka toko dan menandai yang janggal, tanpa mengubah data keuangan.","steps":["Buka halaman Keuangan. Pilih periode (Kemarin, 7 hari, atau Bulan ini) lalu baca pemasukan, pengeluaran, laba kotor, sumber transaksi (POS, Djiwa App, Booking, Jumat Berkah, Merchandise), dan metode pembayaran (tunai, QRIS, dompet, transfer).","Periksa Keuangan → Transaksi untuk pengeluaran besar atau tidak biasa; cocokkan dengan PO dan nota.","Bandingkan laporan shift antar hari: pendapatan, selisih tunai, dan selisih non-tunai.","Tinjau HPP dan margin menu terlaris. Bila margin turun, diskusikan harga atau resep dengan owner.","Setiap kejanggalan dibuat menjadi tugas atau dicantumkan di laporan harian. Jangan menginput ulang transaksi yang sudah ada.","Buat Laporan Keuangan lewat tombol \"Buat laporan keuangan\": harian setiap malam, mingguan setiap Minggu malam, dan bulanan di awal bulan. Dokumen editorial ini terisi otomatis dengan grafik, lalu Anda menambahkan catatan dan rekomendasi sebelum mengirim ke Owner."],"auto":["Setiap transaksi masuk otomatis dibukukan (debit dan kredit).","Pembayaran QRIS dipetakan ke akun bank, lainnya ke kas.","Transaksi ganda dalam 2 menit disaring otomatis.","Pengeluaran berulang dicatat otomatis oleh sistem."],"issue":[["Pengeluaran tampak ganda","Sistem sudah menyaring duplikat; cek sumber transaksi dan nota sebelum menyimpulkan."],["Pendapatan turun tajam","Cek jam tertentu di grafik per jam, status pembayaran tertunda, dan apakah ada menu habis atau gangguan POS."]],"docs":["laporan-keuangan-harian","laporan-keuangan-mingguan","laporan-keuangan-bulanan","laporan-harian-owner","permohonan-pengeluaran"],"open":["Panel Manager → Keuangan","Admin → Keuangan"],"draft":"Batas nominal pengeluaran yang wajib persetujuan owner belum ditetapkan."}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('biaya',9,'Mencatat Pengeluaran: Scan Struk & Telegram','{manager,supervisor}',$j${"id":"biaya","t":"Mencatat Pengeluaran: Scan Struk & Telegram","ic":"payment-wallet","who":"MS","when":"Setiap ada pengeluaran, hari yang sama","goal":"Setiap pengeluaran toko tercatat lengkap dengan bukti, kategori, dan stok yang benar, baik dari aplikasi maupun dari bot Telegram.","steps":["Catat setiap pengeluaran di hari yang sama lewat menu Pengeluaran di aplikasi atau lewat bot Telegram. Keduanya memakai layanan, kategori, dan format yang sama, jadi hasilnya identik.","Scan struk: foto tegak dan terang (boleh banyak struk sekaligus). AI membaca toko, tanggal, item, dan total, lalu menentukan kategori tiap item.","Tinjau hasilnya: tanggal wajib terisi, periksa nama, jumlah, dan harga tiap item, serta tanda ❓ (kategori belum pasti). Total struk harus sama dengan jumlah item.","Pilih kategori utama dan sumber dana. Tautkan ke PO bila struk ini pembelian dari PO. Aktifkan \"Stok +\" untuk item yang cocok dengan inventaris agar stok bertambah. Bila satuannya karton, pack, atau tray, konfirmasi isinya sekali (misalnya 1 karton = 50 pcs); setelah itu otomatis di aplikasi, bot, dan Admin.","Simpan sebagai pengeluaran. Untuk Supervisor, pengeluaran di atas batas persetujuan menunggu Manager; Manager memutuskan di tab Persetujuan.","Tanpa struk (misalnya ongkir atau parkir): gunakan Input manual, atau ketik ke bot, misalnya \"beli susu 2 liter 36000\". Pengeluaran besar wajib foto bukti.","Draf yang dimulai di Telegram bisa dilanjutkan di aplikasi, dan sebaliknya. Foto struk yang sama tidak tersimpan dua kali."],"auto":["Entri akuntansi (debit dan kredit) dibuat otomatis.","Stok bertambah untuk item yang dicocokkan dengan inventaris dan diberi tanda Stok +.","Pesan ke grup Transaksi terkirim dengan format yang sama dari aplikasi maupun bot.","Struk ganda terdeteksi dari foto atau isi yang sama."],"issue":[["Tanggal tidak terbaca","Isi tanggal secara manual. Pengeluaran tanpa tanggal tidak bisa disimpan."],["Total struk tidak sama dengan jumlah item","Periksa item, atau isi diskon, pajak, atau service sesuai struk."],["Bot dan aplikasi menampilkan hal berbeda","Muat ulang. Bila masih berbeda, laporkan lewat tombol Lapor kendala."],["Kategori salah","Ubah kategori item atau kategori utama sebelum menyimpan; AI belajar dari koreksi Anda."]],"docs":["laporan-bug-fitur"],"open":["Menu Pengeluaran","Bot Telegram"],"draft":"Batas persetujuan Manager (default Rp1.000.000) dan batas wajib foto bukti (default Rp100.000) perlu ditetapkan owner."}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('laporan',10,'Menulis Laporan & Dokumen','{manager,supervisor}',$j${"id":"laporan","t":"Menulis Laporan & Dokumen","ic":"order-receipt","who":"MS","when":"Harian & mingguan","goal":"Setiap laporan ke owner singkat, akurat, dan memakai data dari sistem, bukan perkiraan.","steps":["Buka halaman Dokumen. Pilih templat sesuai kebutuhan, baca panduan \"Cara membuat\" dan lihat contoh terisinya.","Ambil angka dari sumber yang disebut di panduan (Laporan Shift, Inventaris, Absensi). Jangan mengetik angka dari ingatan.","Tulis satu kalimat penyebab untuk setiap angka yang janggal, dan satu tindak lanjut dengan penanggung jawab dan tenggat.","Unduh PDF templat bila perlu mengisi manual, lalu isi, foto atau pindai, dan lampirkan ke tugas terkait.","Kirim tepat waktu: laporan harian sebelum 22:30, laporan mingguan Minggu malam atau Senin pagi.","Simpan salinan di tugas terkait supaya mudah dicari saat evaluasi bulanan."],"auto":["Tugas AI mengingatkan jadwal laporan harian dan mingguan.","Lampiran di tugas tersimpan beserta riwayatnya."],"issue":[["Data di laporan berbeda dengan Admin","Selalu ikuti angka di Admin; tulis catatan bila Anda melakukan koreksi manual."],["Tidak sempat menulis lengkap","Kirim versi ringkas (pendapatan, kas, kendala utama) lalu lengkapi besok pagi."]],"docs":["laporan-harian-owner","laporan-mingguan-owner","laporan-belanja-mingguan","notulen-rapat"],"open":["Panel Manager → Dokumen"]}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('prog',11,'Program Khusus: Jumat Berkah & Promo','{manager,supervisor}',$j${"id":"prog","t":"Program Khusus: Jumat Berkah & Promo","ic":"customer-benefit-promo","who":"MS","when":"Mingguan (Kamis–Jumat)","goal":"Program sedekah dan promo berjalan lancar tanpa mengganggu operasional.","steps":["Pesanan Jumat Berkah ditutup Kamis 21.00 WIB; kampanye berikutnya terbuka otomatis. Pantau kuota (default 100 porsi, Rp15.000 per porsi) di Admin → Jumat Berkah.","Saat penutupan, rekap MASAK masuk ke grup Telegram Kitchen. Supervisor memastikan bahan dan kemasan sesuai jumlah porsi.","Jumat 07.00 pengingat masuk ke Kitchen. Pastikan porsi dimasak, dikemas, dan siap didistribusikan.","Setelah distribusi, unggah foto di Admin → Jumat Berkah → Distribusi & Galeri dan tinjau doa donor yang menunggu persetujuan.","Pantau Happy Hour dan diskon aktif di Admin → Diskon; pastikan jam mulai dan berakhir benar."],"auto":["Donasi dibayar via Mayar; kuota dipesan 30 menit dan pembayaran diverifikasi lewat webhook.","Pendapatan dicatat sebagai \"Penjualan Jumat Berkah\" tanpa HPP dan tanpa pengurangan stok.","Notifikasi ke donor dan admin; milestone 50% dan 100% terkirim ke Telegram.","Biaya Mayar ditanggung Djiwa Tentram."],"issue":[["Donasi dibayar tetapi doa belum tayang","Doa yang tidak lolos filter menunggu persetujuan admin; tinjau dan setujui atau tolak."],["Kuota habis","Kuota default 100 porsi per Jumat; ubah di Pengaturan bila ada rencana tambahan."]],"docs":["notulen-rapat"],"open":["Admin → Jumat Berkah","Admin → Diskon","Telegram Kitchen"]}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('mslh',12,'Penanganan Masalah Umum','{manager,supervisor}',$j${"id":"mslh","t":"Penanganan Masalah Umum","ic":"notifications-alerts","who":"MS","when":"Saat dibutuhkan","goal":"Tahu langkah pertama untuk masalah yang paling sering muncul.","steps":["Tenang. Catat jam dan sumber masalah: aplikasi, nomor pesanan, nama karyawan.","Cari masalahnya di tabel panduan cepat dan lakukan langkah pertama.","Bila belum selesai dalam 15 menit, eskalasi ke owner dan buat tugas agar terlacak.","Setelah selesai, tulis ringkasan singkat (apa, kapan, penyebab, tindakan) di catatan harian."],"auto":[],"table":[["POS tidak bisa dipakai / offline","Gunakan mode offline POS bila tersedia; catat transaksi manual; sinkronkan setelah online."],["Pembayaran QRIS gagal","Minta pelanggan coba ulang; cek status di Admin → Pesanan sebelum membuat transaksi baru."],["Bahan habis mendadak","Tandai menu terdampak habis di POS, buat PO darurat, beri tahu tim."],["Selisih kas besar","Jangan tutup buku dulu; hitung ulang, cek pengeluaran belum tercatat, lapor owner dengan Berita Acara."],["Karyawan tidak hadir","Cari pengganti lewat tukar shift atau hubungi cadangan; catat di Approval."],["Aplikasi Customer bermasalah (pelanggan tidak bisa membuka, memesan, atau membayar)","Hubungi Owner SEKARANG (telepon atau Telegram), arahkan pelanggan memesan di kasir, lalu kirim Laporan Bug urgensi Kritis."],["Mesin kopi atau kulkas rusak","Pindahkan bahan dingin, hubungi teknisi, catat sebagai insiden dan ajukan pengeluaran bila perlu."],["Komplain pelanggan","Dengarkan, minta maaf, tawarkan solusi, lalu isi Laporan Insiden."],["Notifikasi atau Telegram tidak masuk","Cek Admin → Pengaturan; sementara pantau langsung di POS dan Admin."],["Pemadaman listrik atau internet","Hentikan penerimaan pesanan online, layani yang ada, catat manual, dan sinkronkan setelah pulih."]],"issue":[],"docs":["laporan-insiden-komplain"],"open":["Admin","POS"]}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('bug',13,'Lapor Bug, Permintaan Fitur & Kendala Aplikasi','{manager,supervisor}',$j${"id":"bug","t":"Lapor Bug, Permintaan Fitur & Kendala Aplikasi","ic":"notifications-alerts","who":"MS","when":"Segera saat terjadi","goal":"Setiap masalah atau permintaan fitur di aplikasi Djiwa Tentram sampai ke owner dengan cepat dan lengkap, terutama bila pelanggan terdampak.","steps":["Kenali apa yang dilaporkan: bug (ada yang rusak), permintaan fitur (ada yang kurang), atau kendala operasional (lambat, tidak bisa diakses) di aplikasi mana pun: Customer, POS, Karyawan, Admin, Booking, atau panel Manager.","KRITIS, lapor segera: bila ada kendala di aplikasi Customer (djiwatentram.web.id), yaitu pelanggan tidak bisa membuka halaman, memesan, atau membayar, atau kasir tidak bisa bertransaksi di POS, hubungi Owner langsung (telepon atau Telegram) saat itu juga. Jangan menunggu laporan tertulis.","Selamatkan bukti: screenshot atau rekaman layar singkat, catat jam, aplikasi, halaman, dan perangkat. Jangan membagikan PIN atau kata sandi.","Buat solusi sementara agar toko tetap berjalan: arahkan pelanggan memesan di kasir, gunakan POS atau catat manual, dan umumkan ke tim.","Kirim laporan tertulis lewat tombol \"Lapor kendala\" di bagian atas aplikasi (templat Laporan Bug, Permintaan Fitur & Kendala). Pilih tingkat urgensi dengan benar.","Pantau tanggapan owner di menu Laporan, lalu beri tahu pelanggan atau tim bila sudah teratasi.","Permintaan fitur: jelaskan masalah yang ingin diselesaikan dan seberapa sering terjadi, supaya owner bisa menentukan prioritas."],"auto":["Laporan masuk ke Owner dengan notifikasi push dan terlihat di admin.djiwatentram.web.id → Laporan masuk.","Owner dapat menjadikan laporan sebagai tugas tindak lanjut untuk Anda."],"th":["Urgensi","Contoh","Tindakan"],"table":[["Kritis","Pelanggan tidak bisa memesan atau membayar di aplikasi Customer; POS tidak bisa bertransaksi","Telepon atau Telegram Owner sekarang, lalu kirim laporan"],["Tinggi","Pesanan online tidak masuk ke dapur; notifikasi tidak berbunyi","Laporan segera, maksimal 15 menit"],["Sedang","Halaman lambat, tampilan salah","Laporan pada hari yang sama"],["Rendah / fitur","Usulan perbaikan atau fitur baru","Laporan, dibahas mingguan"]],"issue":[["Tidak bisa mengirim laporan karena aplikasi Manager sendiri bermasalah","Hubungi Owner lewat Telegram dan kirim screenshot di sana."],["Tidak yakin ini bug atau salah pemakaian","Tetap laporkan beserta langkah yang Anda lakukan. Lebih baik berlebih daripada terlambat."]],"docs":["laporan-bug-fitur","laporan-insiden-komplain"],"open":["Tombol Lapor kendala","Menu Laporan"],"draft":"Nomor kontak darurat Owner dan jam siaga untuk kendala kritis perlu ditetapkan owner."}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_playbook_chapters (slug,position,title,roles,body) values ('prinsip',14,'Prinsip Kerja & Eskalasi','{manager,supervisor}',$j${"id":"prinsip","t":"Prinsip Kerja & Eskalasi","ic":"business-ai-assistant","who":"MS","when":"Selalu","goal":"Aturan emas agar kerja konsisten, data bersih, dan masalah naik ke orang yang tepat.","steps":["Satu sumber data: jangan mencatat ulang di buku atau chat apa yang sudah ada di sistem.","Jangan menghapus data transaksi; batalkan atau koreksi agar ada jejak.","Semua pekerjaan penting masuk ke Tugas supaya terlacak dan terlihat Manager, Supervisor, dan Owner.","Pengeluaran besar atau tidak biasa: konfirmasi owner sebelum dilakukan, gunakan Permohonan Pengeluaran.","Eskalasi bertingkat: karyawan → Supervisor → Manager → Owner. Naikkan bila belum selesai dalam 15 menit atau menyangkut uang, keselamatan, atau reputasi.","Bug, permintaan fitur, atau kendala di aplikasi mana pun: laporkan ke owner lewat tombol Lapor kendala. Kendala di aplikasi Customer yang menghambat pelanggan: hubungi owner langsung.","Setiap pergantian shift diakhiri catatan singkat untuk shift berikutnya."],"auto":[],"issue":[],"docs":["cheat-sheet","permohonan-pengeluaran"],"open":[],"draft":"Batas nominal pengeluaran besar dan kontak eskalasi resmi (nomor owner) perlu ditetapkan owner."}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-harian-owner',0,'Laporan','Laporan Harian ke Owner','{manager}',$j${"id":"laporan-harian-owner","cat":"Laporan","t":"Laporan Harian ke Owner","who":"M","to":"Owner","when":"Setiap malam, sebelum 22:30","fmt":"1 halaman · dikirim via tugas atau grup","purpose":"Memberi owner gambaran singkat hari ini: uang, tim, operasional, dan hal yang perlu diputuskan, tanpa owner harus membuka banyak halaman.","steps":["Tunggu shift ditutup, lalu buka Admin → Keuangan → Laporan Shift dan catat pendapatan, jumlah order, setoran, dan selisih tunai/non-tunai.","Bandingkan pendapatan dengan kemarin (persen naik atau turun) dari Monitor Toko.","Catat kehadiran dari Tim & SDM: yang terlambat, izin, atau tidak hadir beserta alasannya.","Catat kejadian operasional: antrean tertinggi, menu habis, gangguan alat, komplain, dan bagaimana ditangani.","Catat stok kritis dan PO yang sudah dibuat dari halaman Belanja.","Tulis 2–3 tindak lanjut untuk besok, masing-masing dengan penanggung jawab.","Kirim sebelum 22:30 dan lampirkan ke tugas \"Tulis catatan harian untuk owner\"."],"sources":["Admin → Keuangan → Laporan Shift","Panel Manager → Monitor Toko","Panel Manager → Tim & SDM","Admin → Inventaris (stok menipis)","Admin → Jumat Berkah (bila Kamis atau Jumat)"],"tips":["Mulai dari angka, lalu satu kalimat penyebab.","Satu halaman cukup. Detail panjang lampirkan terpisah.","Tulis \"tidak ada\" bila tidak ada kejadian, jangan dikosongkan."],"mistakes":["Menulis angka dari ingatan, bukan dari sistem.","Hanya menulis angka tanpa penyebab dan tindak lanjut.","Mengirim terlambat setelah owner tidur."],"ex":{"title":"Laporan Harian — Sabtu, 14 November 2026","blocks":[{"h":"Ringkasan penjualan","kv":[["Pendapatan","Rp 4.215.000 (kemarin Rp 3.980.000, naik 5,9%)"],["Jumlah order","38 (dine-in 22, takeaway 11, online 5)"],["Rata-rata per order","Rp 110.921"],["Pengeluaran hari ini","Rp 1.100.000 (PO-229 Rp 640.000, servis alat Rp 350.000, utilitas Rp 110.000)"]]},{"h":"Kas","kv":[["Shift Pagi (Andi N.)","Sistem Rp 1.855.000 · fisik Rp 1.850.000 · selisih −Rp 5.000"],["Non-tunai (QRIS)","Sesuai, tidak ada selisih"],["Catatan","Selisih −Rp 5.000 karena kembalian; Berita Acara terlampir"]]},{"h":"Tim","kv":[["Hadir","6 dari 7"],["Terlambat","Andi N. 41 menit (macet)"],["Izin","Bayu Y. sakit, disetujui"]]},{"h":"Operasional","list":["Antrean tertinggi 12 menit pukul 12:15, ditangani dengan menambah satu orang di bar.","1 komplain: kopi terlambat 15 menit, diganti satu minuman.","Susu UHT tinggal 2 L, PO-231 sudah dibuat Supervisor."]},{"h":"Tindak lanjut besok","list":["Terima kiriman PO-231 dan cek kualitas susu — Supervisor, sebelum 10:00.","Susun jadwal pengganti untuk Bayu Y. — Manager, hari ini.","Siapkan bahan Jumat Berkah (64 dari 100 porsi terisi) — Kitchen, malam ini."]},{"sign":[["Dibuat oleh","Manager"],["Diterima oleh","Owner"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-mingguan-owner',1,'Laporan','Laporan Mingguan ke Owner','{manager}',$j${"id":"laporan-mingguan-owner","cat":"Laporan","t":"Laporan Mingguan ke Owner","who":"M","to":"Owner","when":"Minggu malam atau Senin pukul 09:00","fmt":"2 halaman · tabel dan rekomendasi","purpose":"Menunjukkan tren sepekan, margin, dan keputusan yang dibutuhkan, supaya owner bisa mengarahkan minggu berikutnya.","steps":["Buka Admin → Keuangan → Laporan, pilih periode \"Minggu ini\" dan catat pendapatan per hari serta total.","Pilih \"Minggu lalu\" dan hitung selisih persen terhadap minggu ini.","Catat pengeluaran per kategori dari Keuangan → Transaksi dan hitung selisih terhadap pendapatan.","Buka Resep → HPP, catat 3 menu terlaris dan margin masing-masing; tandai yang margin-nya turun.","Rangkum SDM: kehadiran, keterlambatan, izin, dan lembur.","Rangkum kas: berapa kali ada selisih, penyebab, dan tindak lanjutnya.","Tulis 2–3 rekomendasi (maksimal), masing-masing dengan alasan dan perkiraan dampak."],"sources":["Admin → Keuangan → Laporan","Admin → Keuangan → Transaksi","Admin → Resep → HPP","Panel Manager → Tim & SDM","Admin → Jumat Berkah"],"tips":["Bandingkan selalu dengan minggu lalu.","Rekomendasi harus bisa dijalankan, bukan sekadar pengamatan."],"mistakes":["Memasukkan terlalu banyak angka tanpa menyimpulkan.","Tidak menulis keputusan yang diminta dari owner."],"ex":{"title":"Laporan Mingguan — 2 s.d. 8 November 2026","blocks":[{"h":"Pendapatan per hari","cols":["Hari","Pendapatan","Order"],"rows":[["Senin","Rp 3.850.000","34"],["Selasa","Rp 3.920.000","35"],["Rabu","Rp 4.100.000","37"],["Kamis","Rp 4.215.000","38"],["Jumat","Rp 5.380.000","49"],["Sabtu","Rp 6.240.000","57"],["Minggu","Rp 5.470.000","50"]],"total":["Total","Rp 33.175.000","300"]},{"h":"Perbandingan","kv":[["Minggu lalu","Rp 31.020.000"],["Perubahan","Naik 6,9%"],["Hari terbaik","Sabtu (Rp 6.240.000)"]]},{"h":"Pengeluaran","cols":["Kategori","Jumlah"],"rows":[["Bahan baku","Rp 9.800.000"],["Utilitas (listrik, air, gas)","Rp 1.450.000"],["Perawatan alat","Rp 350.000"],["Lain-lain","Rp 410.000"]],"total":["Total","Rp 12.010.000"]},{"h":"Menu terlaris dan margin","cols":["Menu","Terjual","Margin"],"rows":[["Kopi susu","312","68%"],["Nasi ayam bakar","148","52%"],["Teh tarik","121","71%"]]},{"h":"SDM dan kas","list":["Kehadiran 93%; 4 kali terlambat; 2 izin sakit.","Selisih kas terjadi 2 kali (maks. Rp 20.000), keduanya dijelaskan di Berita Acara."]},{"h":"Rekomendasi","list":["Tambah 1 orang di bar pada Sabtu 11:00–14:00, karena antrean mencapai 14 menit.","Tinjau harga nasi ayam bakar: margin 52% turun dari 56% karena harga ayam naik."]},{"sign":[["Dibuat oleh","Manager"],["Diterima oleh","Owner"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('berita-acara-selisih-kas',2,'Form & berita acara','Berita Acara Selisih Kas','{manager}',$j${"id":"berita-acara-selisih-kas","cat":"Form & berita acara","t":"Berita Acara Selisih Kas","who":"M","to":"Owner (arsip)","when":"Saat ada selisih kas ≥ Rp10.000 atau selisih berulang","fmt":"1 halaman · ditandatangani kasir dan Manager","purpose":"Mendokumentasikan selisih kas supaya penyebabnya jelas, tidak berulang, dan ada jejak untuk audit.","steps":["Buka Admin → Keuangan → Laporan Shift dan pilih shift yang ditandai perlu perhatian.","Catat kas sistem, kas fisik, dan selisih tunai; lakukan hal yang sama untuk non-tunai (QRIS).","Minta kasir menghitung ulang per pecahan di depan Anda dan bandingkan dengan rincian pecahan di laporan.","Cek apakah ada pengeluaran shift yang belum dicatat atau kembalian yang tidak biasa.","Tulis penyebab yang paling mungkin dan tindakan perbaikan.","Tanda tangani bersama kasir (atau konfirmasi lewat chat bila sudah pulang) dan lampirkan ke tugas."],"sources":["Admin → Keuangan → Laporan Shift","POS → rincian pecahan shift","Admin → Keuangan → Transaksi"],"tips":["Tulis fakta dulu, dugaan terakhir.","Selisih kecil berulang lebih mengkhawatirkan daripada satu selisih besar."],"mistakes":["Menyalahkan kasir tanpa menghitung ulang.","Menutup buku tanpa penjelasan tertulis."],"ex":{"title":"Berita Acara Selisih Kas","blocks":[{"h":"Identitas","kv":[["Tanggal","14 November 2026"],["Shift","Shift Pagi (07:35–15:00)"],["Kasir","Andi N."],["Dibuat oleh","Manager"]]},{"h":"Perhitungan","cols":["Jenis","Sistem","Fisik / konfirmasi","Selisih"],"rows":[["Tunai","Rp 1.855.000","Rp 1.850.000","−Rp 5.000"],["Non-tunai (QRIS)","Rp 2.360.000","Rp 2.360.000","Rp 0"]]},{"h":"Penyebab","p":"Dua transaksi tunai sore hari dikembalikan dengan nominal yang kurang Rp 2.000 dan Rp 3.000 karena uang receh habis. Tidak ditemukan pengeluaran yang belum dicatat."},{"h":"Tindakan perbaikan","list":["Kasir menambah stok uang receh sebelum jam sibuk (Rp 100.000 pecahan kecil).","Manager memeriksa laci kas pada pukul 11:30 selama minggu ini."]},{"sign":[["Kasir","Andi N."],["Manager","Fakhri A."]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-insiden-komplain',3,'Form & berita acara','Laporan Insiden & Komplain','{manager,supervisor}',$j${"id":"laporan-insiden-komplain","cat":"Form & berita acara","t":"Laporan Insiden & Komplain","who":"MS","to":"Manager / Owner","when":"Maksimal akhir hari terjadinya kejadian","fmt":"1 halaman","purpose":"Mencatat kejadian di luar kebiasaan (komplain, kerusakan, kecelakaan kecil, kehilangan) agar bisa ditindaklanjuti dan dicegah berulang.","steps":["Catat waktu, tempat, dan orang yang terlibat saat kejadian masih segar.","Tulis kronologi singkat berdasarkan fakta: apa yang terjadi, apa yang dilihat.","Catat nomor pesanan atau data terkait dari Admin → Pesanan.","Tulis penanganan saat itu dan kompensasi bila ada (ganti minuman, diskon).","Tulis penyebab dan langkah pencegahan.","Lampirkan foto atau video bila ada, dan kirim ke Manager."],"sources":["Admin → Pesanan","Foto atau video dari ponsel","Admin → Customer Service"],"tips":["Gunakan bahasa netral.","Tulis nama pelanggan hanya bila perlu tindak lanjut."],"mistakes":["Menunda sampai besok sehingga detail lupa.","Menulis opini, bukan fakta."],"ex":{"title":"Laporan Insiden — Komplain Pelanggan","blocks":[{"h":"Identitas kejadian","kv":[["Tanggal & jam","14 November 2026 · 12:20"],["Jenis","Komplain pelayanan (waktu tunggu)"],["Pesanan","ORD-POS-D-0017"],["Dilaporkan oleh","Manager"]]},{"h":"Kronologi","p":"Pelanggan memesan kopi susu dan nasi ayam bakar pukul 12:05. Pada jam sibuk, pesanan baru selesai pukul 12:20. Pelanggan menyampaikan keluhan di kasir."},{"h":"Penanganan","list":["Manager meminta maaf langsung dan menjelaskan kondisi antrean.","Kopi susu diganti satu gelas tanpa biaya."]},{"h":"Penyebab dan pencegahan","list":["Satu barista menangani 9 pesanan bersamaan.","Tambah satu orang di bar pada 11:30–13:30 mulai Jumat."]},{"sign":[["Dibuat oleh","Manager"],["Diketahui","Owner"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('evaluasi-karyawan',4,'SDM','Evaluasi Kinerja Karyawan','{manager}',$j${"id":"evaluasi-karyawan","cat":"SDM","t":"Evaluasi Kinerja Karyawan","who":"M","to":"Owner & karyawan","when":"Bulanan, atau setelah masa percobaan","fmt":"1 halaman · dibahas tatap muka","purpose":"Memberi penilaian yang adil dan terukur, serta target perbaikan yang jelas untuk tiap karyawan.","steps":["Ambil data kehadiran dan keterlambatan dari Tim & SDM untuk satu periode.","Nilai tiap aspek dengan skala 1–5 berdasarkan kejadian nyata, bukan kesan.","Tulis satu hal yang sudah baik dan satu hal yang perlu diperbaiki.","Tetapkan 1–2 target untuk bulan depan yang spesifik dan bisa diukur.","Bahas langsung dengan karyawan, catat tanggapannya, lalu simpan."],"sources":["Panel Manager → Tim & SDM","Admin → Tim Operasional","Catatan insiden dan komplain"],"tips":["Berikan contoh nyata untuk setiap nilai.","Mulai dari hal baik, lalu perbaikan."],"mistakes":["Menilai berdasarkan kejadian terakhir saja.","Target yang terlalu umum, misalnya \"lebih rajin\"."],"ex":{"title":"Evaluasi Kinerja — Oktober 2026","blocks":[{"h":"Identitas","kv":[["Nama","Dwi R."],["Peran","Barista"],["Periode","1–31 Oktober 2026"],["Kehadiran","26 dari 27 hari (96%), terlambat 1 kali"]]},{"h":"Penilaian (1–5)","cols":["Aspek","Nilai","Catatan"],"rows":[["Kehadiran & ketepatan waktu","5","Hampir tanpa keterlambatan"],["Kebersihan area kerja","4","Perlu rutin membersihkan grinder"],["Kecepatan & kualitas minuman","4","Cepat saat sibuk, konsisten"],["Pelayanan & sikap","5","Ramah, sering dipuji pelanggan"],["Kerja sama tim","4","Aktif membantu kasir"]]},{"h":"Catatan","p":"Sangat dapat diandalkan di jam sibuk. Perlu meningkatkan kebiasaan membersihkan peralatan di tengah shift."},{"h":"Target bulan depan","list":["Membersihkan grinder setiap 4 jam dan mencentang di checklist.","Melatih satu barista baru untuk menu dasar."]},{"sign":[["Karyawan","Dwi R."],["Manager","Fakhri A."]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('notulen-rapat',5,'SDM','Notulen Rapat Tim','{manager}',$j${"id":"notulen-rapat","cat":"SDM","t":"Notulen Rapat Tim","who":"M","to":"Tim & Owner","when":"Maksimal 1 jam setelah rapat selesai","fmt":"1 halaman","purpose":"Mencatat keputusan dan tugas dari rapat supaya tidak hilang dan bisa dilacak sampai selesai.","steps":["Tulis tanggal, peserta, dan agenda sebelum rapat dimulai.","Catat keputusan, bukan seluruh percakapan.","Untuk setiap tindak lanjut tulis penanggung jawab dan tenggat.","Buat tindak lanjut itu sebagai tugas di panel agar terlacak.","Bagikan notulen ke peserta dan owner."],"sources":["Agenda rapat","Panel Manager → Tugas"],"tips":["Tugas tanpa nama dan tenggat sama dengan tidak ada tugas."],"mistakes":["Menunda penulisan sampai keesokan harinya."],"ex":{"title":"Notulen Rapat Mingguan","blocks":[{"h":"Informasi","kv":[["Tanggal","Selasa, 10 November 2026 · 15:00"],["Peserta","Manager, Supervisor, perwakilan bar, dapur, kasir"],["Agenda","Evaluasi pekan lalu, persiapan Jumat Berkah, jadwal"]]},{"h":"Keputusan","list":["Jumat Berkah: bahan disiapkan Kamis sore, packing mulai pukul 05:30 Jumat.","Tambah satu barista pada Sabtu siang mulai pekan ini."]},{"h":"Tindak lanjut","cols":["Tugas","Penanggung jawab","Tenggat"],"rows":[["Belanja bahan Jumat Berkah (100 porsi)","Supervisor","Kamis 12:00"],["Susun jadwal Sabtu dengan tambahan barista","Manager","Selasa"],["Ganti papan harga menu","Manager","Jumat"]]},{"sign":[["Notulis","Manager"],["Diketahui","Owner"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('permohonan-pengeluaran',6,'Form & berita acara','Permohonan Persetujuan Pengeluaran','{manager,supervisor}',$j${"id":"permohonan-pengeluaran","cat":"Form & berita acara","t":"Permohonan Persetujuan Pengeluaran","who":"MS","to":"Owner","when":"Sebelum pengeluaran di atas batas yang ditetapkan owner","fmt":"1 halaman · menunggu persetujuan","purpose":"Meminta persetujuan owner atas pengeluaran besar dengan alasan, pilihan, dan nilai yang jelas, sebelum uang keluar.","steps":["Tulis kebutuhan dan dampaknya bila tidak dilakukan.","Kumpulkan minimal dua penawaran atau harga pembanding.","Tulis pilihan yang direkomendasikan dan alasannya.","Lampirkan penawaran atau foto, lalu kirim ke owner via tugas.","Tunggu persetujuan tertulis sebelum membayar atau memesan."],"sources":["Penawaran supplier atau teknisi","Admin → Keuangan → Transaksi (pengeluaran serupa sebelumnya)"],"tips":["Tuliskan risiko bila ditunda."],"mistakes":["Membayar dulu baru meminta persetujuan."],"ex":{"title":"Permohonan Pengeluaran — Servis Mesin Espresso","blocks":[{"h":"Ringkasan","kv":[["Tanggal","14 November 2026"],["Diajukan oleh","Manager"],["Nilai","Rp 1.850.000"],["Kategori","Perawatan alat"]]},{"h":"Alasan","p":"Tekanan mesin espresso turun dan menyebabkan rasa tidak konsisten. Bila ditunda, risiko mesin berhenti saat jam sibuk."},{"h":"Pembanding","cols":["Penyedia","Biaya","Garansi"],"rows":[["Teknisi A","Rp 1.850.000","3 bulan"],["Teknisi B","Rp 2.100.000","1 bulan"]]},{"h":"Rekomendasi","p":"Teknisi A: biaya lebih rendah dan garansi lebih panjang."},{"sign":[["Diajukan oleh","Manager"],["Disetujui oleh","Owner"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('form-po',7,'Pembelian','Formulir Purchase Order (PO)','{supervisor}',$j${"id":"form-po","cat":"Pembelian","t":"Formulir Purchase Order (PO)","who":"S","to":"Supplier (salinan ke Manager)","when":"Setiap pembelian bahan","fmt":"1 halaman · dicetak atau dikirim chat","purpose":"Memastikan pesanan ke supplier tertulis jelas (barang, jumlah, harga, jadwal), supaya bisa dicek saat barang datang.","steps":["Buka Belanja & PO dan periksa draf PO dari AI untuk bahan menipis.","Pastikan supplier, item, jumlah, satuan, dan harga satuan benar. Ubah bila perlu.","Hitung subtotal tiap item dan total PO.","Tulis jadwal kirim, cara pembayaran, dan catatan khusus (misalnya suhu bahan dingin).","Kirim ke supplier, simpan bukti konfirmasi, lalu ubah status menjadi Dipesan."],"sources":["Panel Manager → Belanja & PO","Admin → Inventaris (harga beli terakhir)"],"tips":["Selalu bandingkan dengan harga beli terakhir.","Cantumkan nomor PO di nota supplier."],"mistakes":["Memesan lisan tanpa catatan.","Tidak menulis jadwal kirim."],"ex":{"title":"Purchase Order — PO-231","blocks":[{"h":"Informasi","kv":[["Tanggal","14 November 2026"],["Supplier","UD Segar Jaya"],["Dibuat oleh","Supervisor / Purchasing"],["Jadwal kirim","15 November 2026, sebelum 10:00"]]},{"h":"Item","cols":["Bahan","Jumlah","Harga satuan","Subtotal"],"rows":[["Susu UHT","18 L","Rp 18.000","Rp 324.000"],["Gula pasir","10 kg","Rp 16.000","Rp 160.000"]],"total":["Total","","","Rp 484.000"]},{"h":"Syarat","kv":[["Pembayaran","Transfer setelah barang diterima"],["Catatan","Susu harus tanggal kedaluwarsa minimal 3 bulan"]]},{"sign":[["Dibuat oleh","Supervisor"],["Konfirmasi supplier","UD Segar Jaya"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('berita-acara-terima-barang',8,'Pembelian','Berita Acara Terima Barang','{supervisor}',$j${"id":"berita-acara-terima-barang","cat":"Pembelian","t":"Berita Acara Terima Barang","who":"S","to":"Manager (arsip)","when":"Setiap barang dari supplier tiba","fmt":"1 halaman","purpose":"Memastikan barang yang datang sesuai pesanan, dalam kondisi baik, dan jumlahnya cocok dengan PO sebelum PO ditandai Diterima.","steps":["Siapkan salinan PO dan buka halaman Belanja & PO.","Hitung jumlah setiap barang dan cocokkan dengan PO.","Periksa kondisi: kemasan, suhu untuk bahan dingin, dan tanggal kedaluwarsa.","Catat selisih jumlah atau barang rusak, dan foto bila ada.","Tanda tangani bersama kurir. Bila sesuai, ubah status PO ke Diterima.","Simpan nota dan perbarui harga beli terakhir."],"sources":["Panel Manager → Belanja & PO","Nota supplier"],"tips":["Periksa di depan kurir, sebelum kurir pergi."],"mistakes":["Menandai Diterima tanpa menghitung.","Tidak mencatat tanggal kedaluwarsa."],"ex":{"title":"Berita Acara Terima Barang — PO-231","blocks":[{"h":"Informasi","kv":[["Tanggal terima","15 November 2026 · 09:40"],["Supplier","UD Segar Jaya"],["Penerima","Supervisor"],["Nomor PO","PO-231"]]},{"h":"Pemeriksaan","cols":["Bahan","Dipesan","Diterima","Kondisi"],"rows":[["Susu UHT","18 L","18 L","Baik, kedaluwarsa Feb 2027"],["Gula pasir","10 kg","9 kg","Kurang 1 kg"]]},{"h":"Catatan","p":"Gula pasir kurang 1 kg. Kurir akan mengirim kekurangan besok; nilai disesuaikan di nota."},{"sign":[["Penerima","Supervisor"],["Kurir","(tanda tangan)"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-opname',9,'Pembelian','Laporan Stok Opname','{manager,supervisor}',$j${"id":"laporan-opname","cat":"Pembelian","t":"Laporan Stok Opname","who":"MS","to":"Manager","when":"Terjadwal (bar Selasa, dapur Rabu) dan audit bulanan","fmt":"1 halaman","purpose":"Membandingkan stok fisik dengan sistem, menemukan selisih, dan menetapkan penyebab serta perbaikannya.","steps":["Hitung stok fisik tiap bahan lebih dulu, tanpa melihat angka sistem.","Catat angka fisik dan bandingkan dengan stok sistem di Inventaris.","Hitung selisih dan tulis kemungkinan penyebab (porsi, terbuang, belum dicatat).","Tandai bahan dengan selisih berulang untuk diperiksa resepnya.","Kirim laporan ke Manager dan lampirkan ke tugas opname."],"sources":["Admin → Inventaris","Karyawan → Opname","Admin → Stock Overview"],"tips":["Hitung dua kali untuk bahan mahal."],"mistakes":["Menyalin angka sistem sebagai angka fisik."],"ex":{"title":"Laporan Stok Opname — Bar","blocks":[{"h":"Informasi","kv":[["Tanggal","11 November 2026"],["Area","Bar"],["Petugas","Dwi R.; diperiksa Supervisor"]]},{"h":"Hasil","cols":["Bahan","Sistem","Fisik","Selisih","Keterangan"],"rows":[["Biji kopi arabica","4,0 kg","3,7 kg","−0,3 kg","Kemungkinan porsi"],["Susu UHT","12 L","12 L","0","Sesuai"],["Gelas 12oz","210","204","−6","Rusak/jatuh"]]},{"h":"Tindak lanjut","list":["Periksa takaran grinder untuk arabica.","Catat gelas rusak sebagai terbuang."]},{"sign":[["Petugas","Dwi R."],["Diperiksa","Supervisor"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('perbandingan-supplier',10,'Pembelian','Perbandingan Harga Supplier','{supervisor}',$j${"id":"perbandingan-supplier","cat":"Pembelian","t":"Perbandingan Harga Supplier","who":"S","to":"Manager","when":"Mingguan untuk bahan utama atau saat harga naik","fmt":"1 halaman","purpose":"Memilih supplier berdasarkan harga, kualitas, dan ketepatan kirim, bukan kebiasaan.","steps":["Pilih bahan utama yang dibandingkan.","Minta penawaran dari minimal dua supplier dengan jumlah yang sama.","Catat harga satuan, minimum order, jadwal kirim, dan kualitas yang pernah diterima.","Tulis supplier yang direkomendasikan beserta alasannya.","Kirim ke Manager; bila perubahan signifikan, minta persetujuan owner."],"sources":["Admin → Inventaris (harga beli terakhir)","Penawaran supplier"],"tips":["Jangan menilai harga saja; tanyakan keandalan kirim."],"mistakes":["Membandingkan kualitas yang berbeda."],"ex":{"title":"Perbandingan Supplier — Susu UHT","blocks":[{"h":"Informasi","kv":[["Tanggal","14 November 2026"],["Bahan","Susu UHT full cream, 1 L"],["Dibuat oleh","Supervisor"]]},{"h":"Perbandingan","cols":["Supplier","Harga/L","Min. order","Kirim","Catatan"],"rows":[["UD Segar Jaya","Rp 18.000","12 L","Besok","Langganan, naik 6%"],["Toko Susu Mandiri","Rp 17.200","24 L","2 hari","Belum pernah dipakai"],["Distributor Nusa","Rp 17.800","12 L","Besok","Tepat waktu 3 kali"]]},{"h":"Rekomendasi","p":"Pindahkan sebagian pesanan ke Distributor Nusa (Rp 17.800, kirim besok) dan pertahankan UD Segar Jaya sebagai cadangan."},{"sign":[["Dibuat oleh","Supervisor"],["Disetujui","Manager"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-belanja-mingguan',11,'Pembelian','Laporan Belanja Mingguan','{supervisor}',$j${"id":"laporan-belanja-mingguan","cat":"Pembelian","t":"Laporan Belanja Mingguan","who":"S","to":"Manager","when":"Sabtu sore atau Minggu pagi","fmt":"1 halaman","purpose":"Memberi Manager gambaran pembelian sepekan: nilai, perubahan harga, dan stok yang sering menipis.","steps":["Buka daftar PO sepekan di Belanja & PO dan jumlahkan yang berstatus Diterima.","Catat bahan yang harganya berubah dibanding pembelian sebelumnya.","Catat bahan yang menipis lebih dari dua kali, penyebabnya, dan usulan batas minimum baru.","Tulis masalah dengan supplier (telat, tidak sesuai) dan tindak lanjutnya.","Kirim ke Manager sebelum Minggu siang."],"sources":["Panel Manager → Belanja & PO","Admin → Inventaris"],"tips":["Cantumkan nilai rupiah, bukan hanya jumlah PO."],"mistakes":["Tidak menyebut bahan yang sering menipis."],"ex":{"title":"Laporan Belanja Mingguan — 2 s.d. 8 November 2026","blocks":[{"h":"Ringkasan","kv":[["Jumlah PO","9 (8 diterima, 1 berjalan)"],["Total belanja diterima","Rp 8.640.000"],["Selisih vs minggu lalu","Naik 4,2%"]]},{"h":"Perubahan harga","cols":["Bahan","Sebelumnya","Sekarang","Perubahan"],"rows":[["Susu UHT","Rp 17.000","Rp 18.000","Naik 5,9%"],["Telur","Rp 2.100","Rp 2.200","Naik 4,8%"]]},{"h":"Stok sering menipis","list":["Susu UHT menipis 3 kali; usul batas minimum naik dari 10 L menjadi 15 L."]},{"h":"Masalah supplier","list":["Kopi Nusantara terlambat 1 hari pada PO-226; sudah diingatkan."]},{"sign":[["Dibuat oleh","Supervisor"],["Diterima","Manager"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('berita-acara-retur',12,'Pembelian','Berita Acara Barang Rusak / Retur','{supervisor}',$j${"id":"berita-acara-retur","cat":"Pembelian","t":"Berita Acara Barang Rusak / Retur","who":"S","to":"Manager & supplier","when":"Saat barang rusak, kurang, atau tidak sesuai ditemukan","fmt":"1 halaman · lampirkan foto","purpose":"Menjadi bukti bahwa barang bermasalah dan dasar penggantian atau pengurangan tagihan dari supplier.","steps":["Pisahkan barang bermasalah dan jangan dipakai.","Foto barang, kemasan, dan nota dari beberapa sisi.","Isi berita acara: barang, jumlah, masalah, dan nomor PO.","Hubungi supplier dan sepakati penggantian atau pengurangan tagihan.","Catat kesepakatan, lampirkan ke tugas, dan beri tahu Manager."],"sources":["Panel Manager → Belanja & PO","Foto dari ponsel"],"tips":["Lapor di hari yang sama, supplier biasanya membatasi waktu klaim."],"mistakes":["Memakai barang yang sudah dipermasalahkan."],"ex":{"title":"Berita Acara Barang Rusak — PO-224","blocks":[{"h":"Informasi","kv":[["Tanggal","12 November 2026"],["Supplier","Plastik Mandiri"],["Nomor PO","PO-224"],["Dilaporkan oleh","Supervisor"]]},{"h":"Barang bermasalah","cols":["Barang","Jumlah","Masalah"],"rows":[["Gelas 12oz (karton 3)","1 karton","Retak/penyok, 50 pcs tidak layak pakai"]]},{"h":"Kesepakatan","p":"Supplier mengganti 1 karton pada pengiriman berikutnya (16 November) tanpa biaya tambahan."},{"sign":[["Dilaporkan oleh","Supervisor"],["Diketahui","Manager"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('checklist-buka-tutup',13,'Checklist','Checklist Buka & Tutup Toko','{manager,supervisor}',$j${"id":"checklist-buka-tutup","cat":"Checklist","t":"Checklist Buka & Tutup Toko","who":"MS","to":"Arsip harian","when":"Setiap hari, buka dan tutup","fmt":"1 halaman · cetak dan tempel","purpose":"Memastikan semua langkah buka dan tutup dikerjakan dengan urutan yang sama setiap hari, siapa pun yang bertugas.","steps":["Cetak lembar ini dan tempel di area kerja, atau gunakan versi digital di panel.","Centang setiap langkah setelah benar-benar dikerjakan, bukan sebelumnya.","Tulis catatan di kolom keterangan bila ada yang tidak normal.","Bagian checklist kebersihan sama dengan checklist wajib saat absen keluar: Bar & Kitchen, Area Customer, Toilet/WC (Bersih / Perlu Perbaikan).","Serahkan ke Manager atau simpan sebagai arsip harian."],"sources":["Playbook → Buka Toko","Playbook → Tutup Shift","Karyawan → Absen Keluar"],"tips":["Foto bagian yang Perlu Perbaikan sebagai bukti."],"mistakes":["Mencentang sekaligus di akhir hari."],"ex":{"title":"Checklist Buka & Tutup — Sabtu, 14 November 2026","blocks":[{"h":"Buka toko","check":[["Karyawan jadwal pagi sudah clock-in",true],["Shift dibuka dan kas awal tercatat",true],["Mesin kopi, kulkas, kompor menyala",true],["Menu dan harga POS sesuai",true],["Stok menipis sudah diteruskan ke Supervisor",false]]},{"h":"Tutup toko","check":[["Uang tunai dihitung per pecahan dan dicocokkan",false],["Bar & Kitchen: Bersih / Perlu Perbaikan",false],["Area Customer: Bersih / Perlu Perbaikan",false],["Toilet/WC: Bersih / Perlu Perbaikan",false],["Peralatan mati, sampah dibuang, toko dikunci",false]]},{"h":"Keterangan","p":"(Tulis bila ada hal tidak normal: alat bermasalah, bahan habis, kejadian khusus.)"},{"sign":[["Pembuka","Manager"],["Penutup","Manager"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('cheat-sheet',14,'Checklist','Kartu Cepat Manager & Supervisor','{manager,supervisor}',$j${"id":"cheat-sheet","cat":"Checklist","t":"Kartu Cepat Manager & Supervisor","who":"MS","to":"Dibaca sendiri","when":"Tempel di meja atau simpan di ponsel","fmt":"1 halaman · ringkasan Playbook","noBlank":true,"purpose":"Ringkasan satu halaman: ritme harian, aturan emas, dan siapa dihubungi saat bermasalah.","steps":["Baca saat onboarding, lalu cetak atau simpan.","Gunakan sebagai pegangan cepat saat sedang sibuk atau bingung.","Perbarui bila Playbook berubah; versi terbaru ada di panel."],"sources":["Panel Manager → Playbook SOP"],"tips":["Hafalkan tiga titik paling penting untuk peran Anda."],"mistakes":["Mengandalkan ingatan saat kondisi darurat."],"ex":{"title":"Kartu Cepat Playbook","blocks":[{"h":"Ritme harian","cols":["Jam","Yang harus terjadi"],"rows":[["07:00","Tim clock-in, cek mesin dan kulkas"],["07:30","Shift dibuka, stok dicek"],["12:00","Jam sibuk: pantau antrean (di bawah 10 menit)"],["21:30","Shift ditutup, kas diverifikasi"],["22:00","Laporan harian ke owner"]]},{"h":"Aturan emas","list":["Satu sumber data: jangan mencatat ulang apa yang ada di sistem.","Jangan menghapus transaksi; batalkan atau koreksi.","Pengeluaran besar: minta persetujuan owner dulu.","Selisih kas ≥ Rp10.000: tulis Berita Acara.","Belum selesai 15 menit: eskalasi."]},{"h":"Eskalasi","list":["Karyawan → Supervisor → Manager → Owner.","Naikkan bila menyangkut uang, keselamatan, atau reputasi."]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-bug-fitur',15,'Laporan','Laporan Bug, Permintaan Fitur & Kendala Aplikasi','{manager,supervisor}',$j${"id":"laporan-bug-fitur","cat":"Laporan","t":"Laporan Bug, Permintaan Fitur & Kendala Aplikasi","who":"MS","to":"Owner","when":"Segera setelah kendala ditemukan; kendala di aplikasi Customer langsung hubungi Owner dulu","fmt":"1 halaman · lampirkan screenshot atau video","purpose":"Melaporkan masalah atau permintaan fitur di semua aplikasi Djiwa Tentram (Customer, POS, Karyawan, Admin, Booking, panel Manager) agar owner dan tim teknis bisa memperbaikinya dengan cepat.","steps":["Tentukan jenisnya: Bug (ada yang rusak), Permintaan fitur (ada yang kurang), atau Kendala operasional (aplikasi lambat, tidak bisa diakses).","Tentukan urgensi. KRITIS bila pelanggan tidak bisa membuka, memesan, atau membayar di aplikasi Customer (djiwatentram.web.id), atau kasir tidak bisa bertransaksi di POS. Untuk KRITIS, hubungi Owner langsung lebih dulu (telepon atau Telegram), baru kirim laporan ini.","Catat aplikasi, halaman atau alamatnya, jam kejadian, serta perangkat dan browser yang dipakai.","Tulis langkah mengulang dengan urutan jelas, apa yang diharapkan, dan apa yang terjadi.","Lampirkan screenshot atau rekaman layar. Jangan menyertakan PIN, kata sandi, atau data kartu.","Tulis dampaknya: berapa pelanggan atau pesanan terdampak, dan sejak kapan.","Kirim ke Owner lewat menu Laporan. Tombol \"Lapor kendala\" di bagian atas aplikasi membuka formulir ini langsung."],"sources":["Aplikasi yang bermasalah (screenshot atau rekaman layar)","Admin → Pesanan (jumlah pesanan terdampak)","Panel Manager → Dasbor (aktivitas langsung)"],"tips":["Satu laporan untuk satu masalah.","Rekaman layar pendek (10–20 detik) lebih jelas daripada teks panjang.","Untuk permintaan fitur, jelaskan masalah yang ingin diselesaikan, bukan hanya solusinya."],"mistakes":["Hanya menulis \"tidak bisa\" tanpa langkah dan lampiran.","Menunggu sampai akhir hari padahal pelanggan terdampak.","Mengirim PIN atau kata sandi sebagai bukti."],"ex":{"title":"Laporan Bug — Pembayaran QRIS di Aplikasi Customer","blocks":[{"h":"Identitas laporan","kv":[["Aplikasi","Customer (djiwatentram.web.id)"],["Halaman / alamat","Menu → Keranjang → Bayar"],["Jenis","Bug"],["Tingkat urgensi","KRITIS: pelanggan tidak bisa membayar"],["Waktu kejadian","14 November 2026 · 12:40"],["Perangkat & browser","iPhone 14 · Safari 17"],["Dilaporkan oleh","Manager"]]},{"h":"Langkah mengulang","cols":["No","Langkah"],"rows":[["1","Buka halaman menu dan pilih Kopi susu"],["2","Tekan Bayar di keranjang"],["3","Pilih QRIS, layar menjadi putih"]]},{"h":"Yang diharapkan","p":"Pelanggan melihat kode QRIS dan dapat menyelesaikan pembayaran."},{"h":"Yang terjadi","p":"Layar putih dan pesanan tidak terbentuk. Terjadi pada 6 percobaan berturut-turut dari dua perangkat."},{"h":"Dampak","p":"Pelanggan online tidak dapat memesan. Sekitar 5 pesanan gagal dalam 30 menit. Pemesanan di kasir tidak terdampak."},{"h":"Sudah dicoba","check":[["Muat ulang halaman",true],["Keluar lalu masuk kembali",true],["Perangkat atau browser lain",true],["Jaringan internet lain",false]]},{"sign":[["Dilaporkan oleh","Manager"],["Diterima oleh","Owner"]]}]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-keuangan-harian',16,'Laporan keuangan','Laporan Keuangan Harian','{manager}',$j${"id":"laporan-keuangan-harian","cat":"Laporan keuangan","t":"Laporan Keuangan Harian","who":"M","to":"Owner","when":"Setiap malam setelah verifikasi tutup shift","fmt":"Dokumen editorial · 2 halaman dengan grafik","ed":true,"fin":"hari","purpose":"Memberi owner gambaran kondisi keuangan satu hari: pemasukan, pengeluaran, sumber transaksi, metode pembayaran, stock opname, dan hal yang perlu diputuskan.","steps":["Buka halaman Keuangan, pilih periode \"Kemarin\" atau hari yang dilaporkan, dan periksa angka serta grafik.","Tekan \"Buat laporan keuangan → Harian\". Angka, grafik, dan tabel terisi otomatis dari data sistem.","Baca intisari dan tulis ulang bila perlu. Tombol \"Draf narasi AI\" membantu menulis catatan awal dari angka yang ada.","Tulis catatan penyebab untuk perubahan besar (naik atau turun) dan satu tindak lanjut untuk setiap hal janggal.","Isi rekomendasi atau keputusan yang dibutuhkan dari owner.","Periksa pratinjau, lampirkan bukti bila perlu, lalu kirim ke Owner."],"sources":["Panel Manager → Keuangan","Admin → Keuangan → Transaksi dan Laporan Shift","Stock opname terakhir"],"tips":["Pastikan semua shift sudah ditutup sebelum membuat laporan.","Satu kalimat penyebab lebih berguna daripada banyak angka."],"mistakes":["Mengubah angka otomatis secara manual tanpa catatan.","Mengirim sebelum shift terakhir ditutup."],"ex":{"title":"Laporan Keuangan Harian — Jumat, 13 November 2026","blocks":[]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-keuangan-mingguan',17,'Laporan keuangan','Laporan Keuangan Mingguan','{manager}',$j${"id":"laporan-keuangan-mingguan","cat":"Laporan keuangan","t":"Laporan Keuangan Mingguan","who":"M","to":"Owner","when":"Minggu malam atau Senin pukul 09:00","fmt":"Dokumen editorial · 2–3 halaman dengan grafik","ed":true,"fin":"minggu","purpose":"Menunjukkan tren sepekan, perbandingan dengan pekan sebelumnya, margin, dan rekomendasi untuk pekan berikutnya.","steps":["Pilih periode \"7 hari\" di halaman Keuangan dan cermati grafik tren serta perubahan terhadap pekan sebelumnya.","Tekan \"Buat laporan keuangan → Mingguan\" untuk menarik semua angka dan grafik.","Tulis intisari: apa yang naik, apa yang turun, dan penyebabnya.","Periksa menu terlaris, selisih stock opname, dan sumber transaksi yang tumbuh atau turun.","Tulis maksimal tiga rekomendasi dengan alasan dan perkiraan dampak.","Kirim ke Owner sebelum Senin pukul 09:00."],"sources":["Panel Manager → Keuangan (7 hari)","Admin → Keuangan → Laporan","Admin → Resep → HPP"],"tips":["Selalu bandingkan dengan pekan lalu.","Rekomendasi harus bisa dijalankan minggu depan."],"mistakes":["Tidak menyebut keputusan yang diminta dari owner."],"ex":{"title":"Laporan Keuangan Mingguan — 2 s.d. 8 November 2026","blocks":[]}}$j$::jsonb) on conflict (slug) do nothing;
insert into public.mgr_documents (slug,position,category,title,roles,body) values ('laporan-keuangan-bulanan',18,'Laporan keuangan','Laporan Keuangan Bulanan','{manager}',$j${"id":"laporan-keuangan-bulanan","cat":"Laporan keuangan","t":"Laporan Keuangan Bulanan","who":"M","to":"Owner","when":"Tanggal 1–3 bulan berikutnya; laporan berjalan bisa dikirim tengah bulan","fmt":"Dokumen editorial · 3–4 halaman dengan grafik","ed":true,"fin":"bulan","purpose":"Memberi owner gambaran kondisi perusahaan satu bulan: pendapatan, biaya, margin, sumber dan metode pembayaran, serta stok.","steps":["Pilih periode \"Bulan ini\" di halaman Keuangan dan periksa grafik tren harian.","Tekan \"Buat laporan keuangan → Bulanan\".","Tulis intisari kondisi bulan ini terhadap bulan lalu: pendapatan, biaya, margin.","Jelaskan pengeluaran terbesar dan apakah wajar terhadap volume penjualan.","Rangkum stock opname bulanan dan penyebab selisih terbesar.","Tulis rekomendasi untuk bulan berikutnya, lalu kirim ke Owner."],"sources":["Panel Manager → Keuangan (bulan ini)","Admin → Keuangan → Akuntansi","Stock opname bulanan"],"tips":["Pisahkan program khusus (misalnya Jumat Berkah) dari penjualan reguler saat menjelaskan tren."],"mistakes":["Membandingkan periode dengan jumlah hari berbeda tanpa catatan."],"ex":{"title":"Laporan Keuangan Bulanan — 1 s.d. 13 November 2026 (berjalan)","blocks":[]}}$j$::jsonb) on conflict (slug) do nothing;
