-- Seed Playbook & Dokumen dari prototipe v20. Owner mengedit lewat apps/admin (tabel ini), tanpa deploy.
create table if not exists public.mgr_documents (
  slug text primary key,
  position int not null default 0,
  category text not null,
  title text not null,
  roles text[] not null default '{manager,supervisor}',
  body jsonb not null default '{}'::jsonb,
  updated_by text,
  updated_at timestamptz not null default now()
);
alter table public.mgr_documents enable row level security;
revoke all on public.mgr_documents from anon, authenticated;
grant all on public.mgr_documents to service_role;
alter table public.mgr_playbook_chapters alter column body set default '{}'::jsonb;
